values
  ('sales-tracking-tool', 'Sales Tracking Tool', 'Analytique & Pilotage', null, '📉', 'Track and analyze e-commerce sales performance across platforms. Set up KPI dashboards, trend analysis, and performance alerts to catch issues and opportunities early.', 'sales-tracking-tool', 'hybrid', 'sales-analytics', false, false, null, true, 1),
  ('conversion-rate-optimization', 'Conversion Rate Optimization', 'Conversion & Expérience', null, null, null, 'conversion-rate-optimization', 'hybrid', 'funnel-cro', false, false, null, true, 2),
  ('ecommerce-growth-strategy', 'Ecommerce Growth Strategy', 'Fidélisation & Relation client', null, '🚀', 'E-commerce growth strategy advisor. Diagnoses current business health using unit economics (CAC, LTV, AOV, contribution margin), identifies the highest-impact growth opportunities across 5 levers (traffic, conversion, AOV, retention, expansion), and builds a prioritized 90-day growth roadmap. Uses the Ansoff Matrix adapted for e-commerce to evaluate market penetration, channel expansion, product expansion, and new market entry. Includes multichannel readiness assessment (Amazon, Walmart, TikTok Shop, Etsy, DTC/Shopify/Shopify) and product line expansion analysis. No API key required. Use when: (1) planning next phase of e-commerce growth, (2) deciding whether to expand to new channels or products, (3) diagnosing why growth has stalled, (4) prioritizing what to fix or build next.', 'ecommerce-growth-strategy', 'hybrid', 'unit-economics', false, false, null, true, 3),
  ('profit-margin-calculator-shopify', 'Profit Margin Calculator Shopify', 'Prix & Rentabilité', 'shopify', null, 'Shopify/DTC profit margin calculator for sellers. Calculate cost breakdowns including ad spend, CAC, payment processing fees, and 3PL costs. Includes LTV/CAC analysis and DTC-specific benchmarks. No API key required.', 'profit-margin-calculator/profit-margin-calculator-shopify', 'hybrid', 'profit-margin', true, false, null, true, 4),
  ('dropshipping-product-research', 'Dropshipping Product Research', 'Recherche produit & Opportunités', null, '📦', 'Product research for dropshipping businesses. Identify profitable products with reliable suppliers, healthy margins, and manageable competition. Evaluates shipping times, return risk, and marketing viability.', 'dropshipping-product-research', 'hybrid', 'opportunity-score', false, false, null, true, 5),
  ('shopify-seo', 'Shopify Seo', 'SEO & Visibilité', 'shopify', null, null, 'shopify-seo', 'hybrid', 'listing-seo', false, false, null, true, 6),
  ('cross-border-ecommerce', 'Cross Border Ecommerce', 'Stocks & Logistique', null, '✈️', 'Cross-border e-commerce expansion advisor. Scores target markets on 8 weighted dimensions (market size, ecommerce penetration, competition, regulatory complexity, logistics infrastructure, payment ecosystem, cultural distance, IP protection), compares 5 fulfillment models with cost and transit data, provides country-by-country tax/duty compliance guides (EU VAT/IOSS, UK VAT, US sales tax, CA GST, AU GST, JP consumption tax), maps local payment preferences by market, and builds a phased expansion roadmap. No API key required.', 'cross-border-ecommerce', 'hybrid', 'cross-border', false, false, null, true, 7),
  ('supply-chain-optimization-shopify', 'Supply Chain Optimization Shopify', 'Stocks & Logistique', 'shopify', null, 'Supply Chain Bottleneck Analyzer for Shopify/DTC stores. Diagnose cash flow, inventory, shipping costs, and customer acquisition efficiency. Includes CAC/LTV analysis, 3PL cost optimization, and ad spend benchmarks. No API key required for basic analysis.', 'supply-chain-optimization/supply-chain-optimization-shopify', 'hybrid', 'supply-chain', true, false, null, true, 8),
  ('competitor-price-tracker', 'Competitor Price Tracker', 'Veille concurrentielle', null, '📊', 'Set up competitor price tracking and monitoring workflows. Track price changes, detect promotions, analyze pricing patterns, and get alerts for competitive price movements.', 'competitor-price-tracker', 'hybrid', 'price-tracking', false, true, 'Relevés de prix concurrents : saisie manuelle et import CSV disponibles sans clé. Pour une collecte automatique, connecter une source de données marché (API Nexscope ou équivalent).', true, 9),
  ('dynamic-pricing-ecommerce', 'Dynamic Pricing Ecommerce', 'Veille concurrentielle', null, null, 'Design a controlled dynamic-pricing or repricing system for ecommerce products. Use when a seller asks for demand-based, inventory-based, competitor-responsive, or time-based price rules; SKU eligibility; price floors and ceilings; automation approvals; simulations; monitoring; or rollback plans across Amazon, Shopify, TikTok Shop, Walmart, eBay, or other channels. Do not use for a one-time optimal-price calculation or to change live prices without explicit authorization.', 'dynamic-pricing-ecommerce', 'hybrid', 'dynamic-pricing', false, false, null, true, 10),
  ('review-monitoring', 'Review Monitoring', 'Veille concurrentielle', null, '👁️', 'Set up systematic review monitoring across e-commerce platforms. Track new reviews, detect negative review spikes, monitor competitor reviews, and automate review response workflows.', 'review-monitoring', 'hybrid', 'review-analysis', false, true, 'Avis externes : les avis de votre boutique sont analysés nativement. Pour les avis d''une marketplace, importer un export CSV.', true, 11),
  ('ecommerce-customer-retention', 'Ecommerce Customer Retention', 'Fidélisation & Relation client', null, null, null, 'ecommerce-customer-retention', 'reasoning', null, false, false, null, true, 12),
  ('ecommerce-email-marketing-builder', 'Ecommerce Email Marketing Builder', 'Fidélisation & Relation client', null, '📧', 'E-commerce email marketing system builder. Creates complete email automation flows with full copywriting, subject lines, ESP setup instructions, segmentation rules, and annual campaign calendars. Generates copy-paste-ready email sequences for Klaviyo, Omnisend, Mailchimp, or any ESP. Covers welcome series, cart abandonment, browse abandonment, post-purchase, review requests, cross-sell, win-back, VIP/loyalty, replenishment, and sunset flows. Includes A/B test subject line variants, send timing, trigger conditions, branching logic, and seasonal campaign calendar. No API key required. Use when: (1) setting up email marketing for an e-commerce store, (2) writing email sequences and flows, (3) planning seasonal email campaigns.', 'ecommerce-email-marketing-builder', 'reasoning', null, false, false, null, true, 13),
  ('ecommerce-ppc-strategy-planner', 'Ecommerce Ppc Strategy Planner', 'Marketing & Acquisition', null, null, 'Cross-platform PPC strategy planner for ecommerce businesses. Analyzes your product and margins, recommends the right advertising platforms (Google Ads, Meta Ads, TikTok Ads), calculates ROAS targets, allocates budget across channels, and generates platform-specific campaign briefs with ad copy and creative direction. Two modes: (A) Build — design a multi-platform ad strategy from scratch, (B) Optimize — audit existing cross-platform campaigns and reallocate budget. Works for Shopify, WooCommerce, standalone stores, and marketplace sellers expanding to external traffic. No API key required.', 'ecommerce-ppc-strategy-planner', 'reasoning', null, false, true, 'Données de campagnes : connecter la régie concernée (Google Ads, Meta, TikTok Ads) pour importer les performances réelles. Sans connexion, saisie manuelle des indicateurs.', true, 14),
  ('influencer-outreach', 'Influencer Outreach', 'Marketing & Acquisition', null, null, null, 'influencer-outreach', 'reasoning', null, false, false, null, true, 15),
  ('brand-monitoring', 'Brand Monitoring', 'Veille concurrentielle', null, null, 'Brand monitoring tool for tracking mentions across social media platforms. Monitor Reddit, Google News, YouTube, and DuckDuckGo for brand mentions. Includes sentiment analysis, trend tracking, crisis detection, and competitor comparison. No API key required for basic monitoring.', 'brand-monitoring', 'reasoning', null, true, true, 'Surveillance web : nécessite une source de veille (API de recherche ou flux). Sans clé, les mentions sont saisies ou importées manuellement.', true, 16),
  ('ecommerce-competitor-analysis', 'Ecommerce Competitor Analysis', 'Veille concurrentielle', null, null, 'Cross-platform ecommerce competitor analysis and strategic intelligence. Multi-channel presence evaluation, strategy assessment, positioning analysis, and competitive benchmarking. Use when the user asks about competitor analysis, competitive research, market analysis, or competitive intelligence across platforms.', 'ecommerce-competitor-analysis', 'reasoning', null, false, false, null, true, 17),
  ('ecommerce-marketing-strategy-builder', 'Ecommerce Marketing Strategy Builder', 'Veille concurrentielle', null, '🎯', 'Full-stack e-commerce marketing strategy builder. Analyzes your product, market, and competitors, then builds a complete omnichannel marketing plan covering paid ads, SEO, email/SMS, content marketing, social media, influencer partnerships, and referral programs. Includes target audience persona, competitive landscape, channel prioritization with budget allocation, content direction, and a 90-day action plan. Works for any e-commerce platform — Shopify, Amazon, Etsy, WooCommerce, TikTok Shop, and more. No API key required.', 'ecommerce-marketing-strategy-builder', 'reasoning', null, false, false, null, true, 18),
  ('product-description-generator', 'Product Description Generator', 'Veille concurrentielle', null, null, 'E-commerce product description generator for any platform. Generates optimized titles, bullet points, descriptions, and backend keywords using competitor research + keyword scoring + FABE copywriting. Two modes: (A) Create — generate listing from product specs with optional competitor analysis, (B) Optimize — improve existing listing with keyword gap analysis. Supports Amazon, eBay, Walmart, Shopify, Etsy, TikTok Shop, Lazada, Shopee. No API key required. Use when: (1) writing a new product listing, (2) analyzing what makes competitors rank, (3) improving an underperforming listing.', 'product-description-generator', 'reasoning', null, false, false, null, true, 19),
  ('ecommerce-business-plan', 'Ecommerce Business Plan', 'Analytique & Pilotage', null, '📑', 'Create a comprehensive e-commerce business plan. Market analysis, financial projections, marketing strategy, operations planning, and milestone roadmap for new or growing e-commerce businesses.', 'ecommerce-business-plan', 'hybrid', 'unit-economics', false, false, null, false, 20),
