  ('ebay-review-checker', 'Ebay Review Checker', 'Fidélisation & Relation client', 'ebay', null, 'eBay review and feedback authenticity analyzer. Detect fake reviews, suspicious seller feedback patterns, and buyer manipulation. Includes time clustering detection, content similarity analysis, and eBay-specific red flag identification. No API key required.', 'review-checker/ebay-review-checker', 'hybrid', 'review-analysis', true, true, 'Avis externes : les avis de votre boutique sont analysés nativement. Pour les avis d''une marketplace, importer un export CSV.', false, 29),
  ('product-review-analysis', 'Product Review Analysis', 'Fidélisation & Relation client', null, null, 'Product review analysis and customer feedback intelligence. Pain point identification, praise pattern analysis, feature request extraction, sentiment analysis, and product improvement insights. Use when the user asks about review analysis, customer feedback, product reviews, or sentiment analysis.', 'product-review-analysis', 'hybrid', 'review-analysis', false, true, 'Avis externes : les avis de votre boutique sont analysés nativement. Pour les avis d''une marketplace, importer un export CSV.', false, 30),
