  ('tiktok-shop-cross-border', 'Tiktok Shop Cross Border', 'International & Conformité', 'tiktok-shop', null, 'Cross-border selling on TikTok Shop. Market selection, logistics setup, localization strategy, compliance requirements, and international expansion. Use when the user asks about TikTok Shop international selling, cross-border ecommerce, global expansion, or selling in multiple countries.', 'tiktok-shop-cross-border', 'hybrid', 'cross-border', false, false, null, false, 32),
  ('supply-chain-optimization-tiktok', 'Supply Chain Optimization Tiktok', 'Marketing & Acquisition', 'tiktok-shop', null, 'Supply Chain Bottleneck Analyzer for TikTok Shop sellers. Diagnose cash flow, inventory turnover, affiliate commissions, and return rates. Includes FBT cost analysis, influencer payout optimization, and viral product lifecycle management. No API key required for basic analysis.', 'supply-chain-optimization/supply-chain-optimization-tiktok', 'hybrid', 'supply-chain', true, false, null, false, 33),
  ('amazon-review-checker', 'Amazon Review Checker', 'Marque & Réputation', 'amazon', null, 'Amazon review authenticity analyzer. Detect fake reviews, suspicious patterns, and rating manipulation. Includes time clustering detection, content similarity analysis, rating distribution checks, and verified purchase validation. Progressive analysis with L1-L4 depth levels. No API key required.', 'review-checker/amazon-review-checker', 'hybrid', 'review-analysis', true, true, 'Avis externes : les avis de votre boutique sont analysés nativement. Pour les avis d''une marketplace, importer un export CSV.', false, 34),
  ('walmart-review-checker', 'Walmart Review Checker', 'Marque & Réputation', 'walmart', null, 'Walmart review authenticity analyzer. Detect fake reviews, suspicious patterns, and rating manipulation. Includes WFS verified badge analysis, incentivized review detection, and Walmart-specific red flag identification. No API key required.', 'review-checker/walmart-review-checker', 'hybrid', 'review-analysis', true, true, 'Avis externes : les avis de votre boutique sont analysés nativement. Pour les avis d''une marketplace, importer un export CSV.', false, 35),
  ('price-optimization-tool', 'Price Optimization Tool', 'Prix & Rentabilité', null, null, 'Evaluate ecommerce price candidates using unit economics, historical observations, elasticity analysis, scenario modeling, and controlled experiments. Use when a seller asks what price to test, how price changes could affect contribution or revenue, how to estimate elasticity, how to optimize a bundle or tier, or how to design a price experiment across Amazon, Shopify, TikTok Shop, Walmart, eBay, or other channels. Do not claim a proven optimal price without sufficient clean data, and do not change live prices without explicit authorization.', 'price-optimization-tool', 'hybrid', 'dynamic-pricing', false, false, null, false, 36),
  ('profit-margin-calculator-amazon', 'Profit Margin Calculator Amazon', 'Prix & Rentabilité', 'amazon', null, 'Amazon profit margin calculator for sellers. Calculate cost breakdowns, profit margins, break-even points, and get pricing recommendations. Supports single product analysis and batch calculations. Input product cost, shipping, FBA fees, and get instant profitability analysis. No API key required. Use when: (1) evaluating new product profitability before sourcing, (2) diagnosing existing product margins, (3) adjusting pricing strategy, (4) analyzing multiple SKUs at once.', 'profit-margin-calculator/profit-margin-calculator-amazon', 'hybrid', 'profit-margin', true, false, null, false, 37),
  ('profit-margin-calculator-tiktok', 'Profit Margin Calculator Tiktok', 'Prix & Rentabilité', 'tiktok-shop', null, 'TikTok Shop profit margin calculator for sellers. Calculate cost breakdowns including affiliate commissions, platform fees, and FBT costs. Includes return rate analysis for impulse buying patterns. No API key required.', 'profit-margin-calculator/profit-margin-calculator-tiktok', 'hybrid', 'profit-margin', true, false, null, false, 38),
  ('profit-margin-calculator-walmart', 'Profit Margin Calculator Walmart', 'Prix & Rentabilité', 'walmart', null, 'Walmart profit margin calculator for sellers. Calculate cost breakdowns including WFS fulfillment, storage fees, and referral fees. Includes comparison with Amazon FBA and lower competition advantage analysis. No API key required.', 'profit-margin-calculator/profit-margin-calculator-walmart', 'hybrid', 'profit-margin', true, false, null, false, 39),
  ('shopify-international', 'Shopify International', 'Prix & Rentabilité', 'shopify', null, 'Shopify Markets — multi-currency, translation, duties/taxes, localized pricing, market-specific content', 'shopify-international', 'hybrid', 'cross-border', false, false, null, false, 40),
