  ('market-gap-analysis', 'Market Gap Analysis', 'Recherche produit & Opportunités', null, '🎯', 'Identify underserved market gaps and unmet customer needs in e-commerce. Analyzes competitor blind spots, review pain points, search demand without adequate supply, and emerging customer segments.', 'market-gap-analysis', 'hybrid', 'opportunity-score', false, false, null, false, 42),
  ('product-differentiation-amazon', 'Product Differentiation Amazon', 'Recherche produit & Opportunités', 'amazon', null, 'Amazon product differentiation strategy tool. Analyze competitor weaknesses, extract pain points from negative reviews, identify unique selling points from positive reviews, and generate actionable differentiation strategies. Progressive L1-L4 analysis depth. No API key required.', 'product-differentiation/product-differentiation-amazon', 'hybrid', 'differentiation', true, false, null, false, 43),
  ('product-differentiation-ebay', 'Product Differentiation Ebay', 'Recherche produit & Opportunités', 'ebay', null, 'eBay product differentiation strategy tool. Analyze competitor weaknesses, extract pain points from negative feedback, identify unique selling points, and generate actionable differentiation strategies. Includes eBay-specific seller feedback analysis. No API key required.', 'product-differentiation/product-differentiation-ebay', 'hybrid', 'differentiation', true, false, null, false, 44),
  ('product-differentiation-shopify', 'Product Differentiation Shopify', 'Recherche produit & Opportunités', 'shopify', null, 'Shopify/DTC product differentiation strategy tool. Analyze competitor stores, extract pain points from reviews, identify brand positioning opportunities, and generate actionable differentiation strategies. Includes DTC-specific metrics like CAC, LTV, and brand story analysis. No API key required.', 'product-differentiation/product-differentiation-shopify', 'hybrid', 'differentiation', true, false, null, false, 45),
  ('product-differentiation-tiktok', 'Product Differentiation Tiktok', 'Recherche produit & Opportunités', 'tiktok-shop', null, 'TikTok Shop product differentiation strategy tool. Analyze viral product trends, competitor affiliate strategies, content performance, and identify differentiation opportunities. Includes TikTok-specific metrics like engagement rate, viral potential, and creator collaboration insights. No API key required.', 'product-differentiation/product-differentiation-tiktok', 'hybrid', 'differentiation', true, false, null, false, 46),
