  ('product-page-seo', 'Product Page Seo', 'SEO & Visibilité', null, '🔎', 'Optimize e-commerce product pages for search engine visibility. On-page SEO, structured data, page speed, mobile optimization, and content strategy for Google, Bing, and platform-specific search.', 'product-page-seo', 'hybrid', 'listing-seo', false, false, null, false, 52),
  ('product-title-optimization', 'Product Title Optimization', 'SEO & Visibilité', null, '✏️', 'Optimize product titles for search visibility and click-through rate across e-commerce platforms. Platform-specific title rules for Amazon (200 chars), Etsy (140 chars), Walmart, Shopify SEO, and eBay.', 'product-title-optimization', 'hybrid', 'listing-seo', false, false, null, false, 53),
